451	
452	export interface ResolvedAssignments {
453	  default_model_slug: string | null;
454	  persona_models: Record<string, string>;
455	}
456	
457	/**
458	 * Resolves UUID values in `assignments.json` to slugs using `local.json`.
459	 *
460	 * - Returns `null` for `default_model_slug` when `default_model_uuid` is absent
461	 *   or references an unknown model.
462	 * - Persona entries with unresolvable UUIDs are omitted (graceful degradation).
463	 * - When `assignments.json` does not exist, returns
464	 *   `{ default_model_slug: null, persona_models: {} }`.
465	 */
466	export async function getResolvedAssignments(): Promise<ResolvedAssignments> {
467	  let assignments: ModelAssignments;
468	  try {
469	    assignments = await readAssignments();
470	  } catch {
471	    return { default_model_slug: null, persona_models: {} };
472	  }
473	
474	  let models: ModelEntry[] = [];
475	  try {
476	    models = await readModels();
477	  } catch {
478	    // Registry unavailable — return unresolved empty result
479	    return { default_model_slug: null, persona_models: {} };
480	  }
481	
482	  const uuidToSlug = new Map(models.map((m) => [m.id, m.slug]));
483	
484	  const default_model_slug =
485	    assignments.default_model_uuid !== undefined
486	      ? (uuidToSlug.get(assignments.default_model_uuid) ?? null)
487	      : null;
488	
489	  const persona_models: Record<string, string> = {};
490	  for (const [personaId, uuid] of Object.entries(assignments.persona_models)) {
491	    const slug = uuidToSlug.get(uuid);
492	    if (slug !== undefined) {
493	      persona_models[personaId] = slug;
494	    }
495	    // Unresolvable UUIDs are silently omitted (graceful degradation)
496	  }
497	
498	  return { default_model_slug, persona_models };
499	}
