505	/**
506	 * Reads `default.json`, writes it to `local.json`, and returns the parsed entries.
507	 * Called when `local.json` is absent.
508	 */
509	async function _initializeLocalFromDefault(): Promise<ModelEntry[]> {
510	  let defaultParsed: unknown;
511	  try {
512	    defaultParsed = await readJsonFile(defaultJsonPath());
513	  } catch (err) {
514	    throw new ApiError(
515	      'READ_ERROR',
516	      `Auto-initialization failed: could not read default.json: ${(err as Error).message}`
517	    );
518	  }
519	
520	  const result = ModelRegistrySchema.safeParse(defaultParsed);
521	  if (!result.success) {
522	    throw new ApiError(
523	      'VALIDATION_ERROR',
524	      `Auto-initialization failed: default.json schema validation error: ${result.error.message}`
525	    );
526	  }
527	
528	  await atomicWriteJson(localJsonPath(), result.data);
529	  process.stderr.write(
530	    `[model-registry] local.json not found — auto-initialized from default.json\n`
531	  );
532	  return result.data;
533	}

101	async function writeJson(filePath: string, data: unknown): Promise<void> {
102	  await writeFile(filePath, JSON.stringify(data, null, 2) + '\n', 'utf-8');
103	}
